(()=>{
'use strict';
const state={page:'beranda',stats:{},rows:[],changes:[],auth:null,result:null,provinces:[],selected:null,comments:[],users:[],reports:[],logs:[],profile:null,map:null,terrain:null,terrainAuto:true,terrainRequestedKey:null,measurements:[],chat:[],mapProvince:'',mapArea:'',mapMuxSelection:'',mapUserMarker:null,mapCoordinate:null,mapMarkerIndex:{},pointSelected:null,pointMap:null,mapLastUpdated:null,pointRequests:[]};
const app=document.getElementById('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=s=>esc(s).replace(/`/g,'&#96;');
const send=(action,data={})=>window.parent.postMessage({isStreamlitMessage:true,type:'streamlit:setComponentValue',value:{action,...data,event_id:Date.now().toString(36)+Math.random().toString(36).slice(2)}},'*');
const height=()=>setTimeout(()=>window.parent.postMessage({isStreamlitMessage:true,type:'streamlit:setFrameHeight',height:Math.max(600,document.documentElement.scrollHeight)},'*'),60);
const auth=()=>!!state.auth;
const requireLogin=()=>{if(!auth()){state.page='login';render();notice('Silakan login untuk menggunakan fitur ini.');return false}return true};
const notice=t=>{let n=document.getElementById('globalNotice');if(!n){n=document.createElement('div');n.id='globalNotice';n.className='notice';app.prepend(n)}n.textContent=t};
const statsHTML=()=>`<div class="stats">${[['Provinsi dengan data','provinsi'],['Wilayah layanan','wilayah'],['MUX terdata','mux'],['Nama kanal unik','kanal']].map(([l,k])=>`<div class="stat"><span>${l}</span><strong>${esc(state.stats[k]??'—')}</strong></div>`).join('')}</div>`;
const field=(label,name,placeholder='',type='text',value='')=>`<label class="field">${label}<input name="${name}" type="${type}" placeholder="${attr(placeholder)}" value="${attr(value)}" required></label>`;
const options=(values,selected='')=>values.map(x=>`<option value="${attr(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('');
const rowTitle=r=>`${r.mux} — ${r.wilayah}, ${r.provinsi}`;
function nav(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));document.getElementById('account').textContent=state.auth?`👤 ${state.auth.nama} · ⭐ ${state.auth.points||0} poin`:'';document.getElementById('loginNav').textContent=state.auth?'Keluar':'Login';document.getElementById('loginNav').classList.toggle('logout-nav',!!state.auth);document.getElementById('profileNav').hidden=!auth();document.getElementById('adminNav').hidden=!(state.auth&&state.auth.admin)}
function hasValidTransmitterCoordinates(row){if(!row)return false;const rawLat=row.latitude,rawLon=row.longitude;if(rawLat===null||rawLat===undefined||rawLon===null||rawLon===undefined||String(rawLat).trim()===''||String(rawLon).trim()==='')return false;const lat=Number(rawLat),lon=Number(rawLon);return Number.isFinite(lat)&&Number.isFinite(lon)&&lat>=-11&&lat<=6&&lon>=95&&lon<=141}
function render(){nav();if(state.map){state.map.remove();state.map=null}if(state.pointMap){state.pointMap.remove();state.pointMap=null}
if(state.page==='beranda')app.innerHTML=`<section class="hero"><p class="eyebrow">RUANG INFORMASI SIARAN DIGITAL INDONESIA</p><h1>Terhubung dengan dunia TV digital.</h1><p>Data kanal, wilayah layanan, dan informasi pemancar dalam satu ruang komunitas.</p>${state.auth?`<p class="welcome-user">Selamat datang, <b>${esc(state.auth.nama||state.auth.username)}</b>!</p>`:""}<a class="primary" href="#search" data-page="search">Jelajahi data siaran</a></section>${statsHTML()}<section class="panel"><h2>Selamat datang di KTVDI</h2><p>Platform komunitas untuk berbagi dan memperbarui informasi siaran televisi digital Indonesia.</p><div class="quick-grid"><button data-page="map">🗺️ Peta pemancar</button><button data-page="search">🔎 Cari siaran</button><button data-page="leaderboard">🏆 Kontributor</button></div></section><section class="panel"><h2>Perubahan terbaru</h2>${changeList(5)}</section>`;
else if(state.page==='search')app.innerHTML=`<section class="panel"><h2>🔎 Pencarian siaran global</h2><p class="muted">Cari nama kanal, MUX, wilayah, atau provinsi.</p><form id="searchForm" class="field"><input name="query" placeholder="Contoh: TVRI, UHF 27, Jawa Barat" required><button class="action">Cari data</button></form><div id="results"></div></section>`;
else if(state.page==='database')app.innerHTML=databasePage();
else if(state.page==='statistics')app.innerHTML=`<section class="panel"><h2>📊 Statistik TV Digital Indonesia</h2>${statsHTML()}<h3>MUX dan kanal per provinsi</h3>${provinceStats()}</section>`;
else if(state.page==='notifications')app.innerHTML=`<section class="panel"><h2>🔔 Perubahan data terbaru</h2>${changeList(999999)}</section>`;
else if(state.page==='map'){const located=mapLocatedRows();const provinces=[...new Set(located.map(r=>r.provinsi).filter(Boolean))].sort();const areas=[...new Set(located.filter(r=>(!state.mapProvince||r.provinsi===state.mapProvince)).map(r=>r.wilayah).filter(Boolean))].sort();const muxRows=located.filter(r=>(!state.mapProvince||r.provinsi===state.mapProvince)&&(!state.mapArea||r.wilayah===state.mapArea));const muxOptions=muxRows.map(r=>({value:[r.provinsi,r.wilayah,r.mux].join('|'),label:r.mux}));app.innerHTML=`<section class="panel map-panel"><h2>🗺️ Peta Pemancar & Kualitas Sinyal TV Digital</h2><p class="muted">Pilih Provinsi dan Wilayah Layanan, lalu pilih MUX bertitik. Prediksi terrain akan dihitung otomatis menggunakan data teknis yang tersedia. Gunakan form simulasi hanya jika ingin mengubah parameter dan menghitung ulang. Marker peta hanya menampilkan informasi pemancar.</p><div class="map-filterbar"><label>Provinsi<select id="mapProvinceFilter"><option value="">Semua provinsi</option>${options(provinces,state.mapProvince)}</select></label><label>Wilayah Layanan<select id="mapAreaFilter"><option value="">Semua wilayah</option>${options(areas,state.mapArea)}</select></label><label>Pilih MUX bertitik<select id="mapMuxFilter"><option value="">Pilih MUX pemancar</option>${muxOptions.map(o=>`<option value="${attr(o.value)}" ${o.value===state.mapMuxSelection?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label><button type="button" class="small-action" id="resetMapFilters">Reset filter</button></div><div class="map-container"><div id="map" style="height:600px;border-radius:14px;z-index:1"></div><button type="button" class="map-gps-button" id="mapLocate" title="Lokasi saya" aria-label="Lokasi saya">⌖</button></div><div class="map-status"><span id="mapCount"></span><span id="mapCoordinates">Koordinat: —</span></div><div id="mapLastUpdated" class="map-last-updated">Update titik pemancar terakhir: ${esc(state.mapLastUpdated||"Belum ada riwayat perubahan")}</div><p class="muted map-disclaimer">GPS memerlukan izin lokasi browser dan HTTPS. Prediksi terrain merupakan estimasi berbasis DEM, bukan jaminan penerimaan siaran.</p><section class="terrain-simulation"><h3>🧭 Form Simulasi Prediksi Terrain</h3><p class="muted">Prediksi terrain otomatis menggunakan data teknis pemancar yang tersimpan (atau nilai asumsi jika belum tersedia). Ubah parameter di bawah hanya jika ingin mencoba simulasi alternatif. Nilai simulasi tidak disimpan ke database.</p><form id="terrainSimulationForm" class="simulation-grid">${field('ERP simulasi (W)','sim_erp_w','Default dari data/asumsi','number','1000')}${field('Tinggi antena TX simulasi (m)','sim_tx_height_m','Contoh 30','number','30')}${field('Tinggi antena penerima (m)','sim_rx_height_m','Contoh 10','number','10')}${field('Ambang penerimaan (dBm)','sim_rx_threshold_dbm','Contoh -90','number','-90')}${field('Rugi tambahan (dB)','sim_extra_loss_db','Contoh 4','number','4')}<button class="action" type="submit" ${state.selected?'':'disabled'}>Terapkan simulasi & hitung ulang</button></form><p id="terrainSimulationStatus" class="muted">${state.selected?(state.terrain?'Prediksi otomatis selesai. Ubah parameter jika ingin menghitung simulasi alternatif.':'Prediksi otomatis sedang diproses atau menunggu hasil.'): 'Pilih MUX pada daftar di atas; prediksi terrain akan berjalan otomatis.'}</p>${state.terrain?`<div class="result"><b>Hasil prediksi:</b> ${esc(state.terrain.min_dbm??'—')} hingga ${esc(state.terrain.max_dbm??'—')} dBm · ${esc(state.terrain.prediction_data_status||'Estimasi')}</div>`:''}</section></section>`;}
else if(state.page==='login')app.innerHTML=auth()?`<section class="panel"><h2>Akun KTVDI</h2><p>Anda masuk sebagai <b>${esc(state.auth.nama)}</b>. Untuk keluar, gunakan menu navigasi <b>Keluar</b>.</p></section>`:`<section class="panel form"><h2>🔐 Login akun KTVDI</h2><form id="loginForm">${field('Username','username','Username','text')}${field('Password','password','Password','password')}<button type="button" class="password-toggle" data-toggle-password>👁 Lihat password</button><button class="action">Login</button></form><div class="quick-grid"><button data-page="register">Daftar akun baru</button><button data-page="forgot">Lupa password</button></div></section>`;
else if(state.page==='register')app.innerHTML=`<section class="panel form"><h2>📝 Pendaftaran akun</h2><form id="registerForm">${field('Nama lengkap','nama','Nama lengkap')}${field('Email','email','email@example.com','email')}${field('Username (huruf kecil dan angka)','username','contoh: budi123')}${field('Password (minimal 6 karakter)','password','Password','password')}<button class="action">Kirim OTP</button></form><p class="muted">OTP dikirim melalui email dan berlaku 10 menit.</p><form id="registerVerify">${field('Kode OTP','otp','6 digit','text')}<button class="action secondary">Verifikasi pendaftaran</button></form></section>`;
else if(state.page==='forgot')app.innerHTML=`<section class="panel form"><h2>🔑 Reset password</h2><form id="forgotRequest">${field('Email terdaftar','email','email@example.com','email')}<button class="action">Kirim OTP</button></form><form id="forgotReset">${field('Kode OTP','otp','6 digit')}${field('Password baru','password','Minimal 6 karakter','password')}<button class="action secondary">Reset password</button></form></section>`;
else if(state.page==='addPoint'){
if(!auth()){app.innerHTML=`<section class="panel form"><h2>📍 Kelola Titik Pemancar</h2><p>Login diperlukan untuk menambahkan titik atau mengajukan perubahan titik.</p><button data-page="login" class="action">Login / Daftar Akun</button></section>`;}
else{
const rows=[...state.rows].sort((a,b)=>`${a.provinsi}/${a.wilayah}/${a.mux}`.localeCompare(`${b.provinsi}/${b.wilayah}/${b.mux}`));
if(!state.pointSelected||!rows.some(r=>[r.provinsi,r.wilayah,r.mux].join('|')===state.pointSelected))state.pointSelected=(rows.find(r=>!hasValidTransmitterCoordinates(r))||rows[0])?[((rows.find(r=>!hasValidTransmitterCoordinates(r))||rows[0]).provinsi),((rows.find(r=>!hasValidTransmitterCoordinates(r))||rows[0]).wilayah),((rows.find(r=>!hasValidTransmitterCoordinates(r))||rows[0]).mux)].join('|'):null;
const chosen=rows.find(r=>[r.provinsi,r.wilayah,r.mux].join('|')===state.pointSelected);
const hasCoords=chosen&&hasValidTransmitterCoordinates(chosen);
const isAdmin=!!state.auth?.admin;
const pointOwner=chosen?.point_added_by_username||'';
const isCreator=!!pointOwner&&pointOwner===state.auth?.username;
const canManagePoint=isAdmin||isCreator;
const pendingForChosen=(state.pointRequests||[]).filter(q=>q.provinsi===chosen?.provinsi&&q.wilayah===chosen?.wilayah&&q.mux===chosen?.mux);
const ownPending=pendingForChosen.find(q=>q.requester===state.auth?.username&&q.status==='Menunggu');
const ownApproved=pendingForChosen.find(q=>q.requester===state.auth?.username&&q.status==='Disetujui');
const reviewable=pendingForChosen.filter(q=>q.status==='Menunggu'&&(isAdmin||(pointOwner&&pointOwner===state.auth?.username)));
const reviewableAll=(state.pointRequests||[]).filter(q=>q.status==='Menunggu'&&(isAdmin||(q.point_added_by_username&&q.point_added_by_username===state.auth?.username)));
const approvalInbox=reviewableAll.length?`<section class="result"><h3>${isAdmin?'Kotak Masuk Persetujuan Admin':'Permohonan untuk titik yang Anda buat'}</h3><p class="muted">Semua permohonan yang dapat Anda putuskan, tidak bergantung pada titik yang sedang dipilih.</p>${reviewableAll.map(q=>`<article class="result"><b>${esc(q.requester_name||q.requester)}</b><p><b>${esc(q.mux||'')}</b> — ${esc(q.wilayah||'')}, ${esc(q.provinsi||'')}</p><p>${esc(q.reason||'')}</p><small>${esc(q.requested_at||'')}</small><div class="map-toolbar"><button type="button" class="small-action" data-point-approve="${attr(q.requester)}" data-provinsi="${attr(q.provinsi)}" data-wilayah="${attr(q.wilayah)}" data-mux="${attr(q.mux)}">Setujui</button><button type="button" class="small-action danger" data-point-reject="${attr(q.requester)}" data-provinsi="${attr(q.provinsi)}" data-wilayah="${attr(q.wilayah)}" data-mux="${attr(q.mux)}">Tolak</button></div></article>`).join('')}</section>`:`<section class="result"><h3>${isAdmin?'Kotak Masuk Persetujuan Admin':'Permohonan untuk titik yang Anda buat'}</h3><p class="muted">Belum ada permohonan yang menunggu persetujuan Anda.</p></section>`;
app.innerHTML=`<section class="panel form"><h2>📍 Kelola Titik Pemancar</h2>
${approvalInbox}
<p class="muted">Pengelolaan titik terpisah dari kepemilikan MUX. Pembuat titik dapat mengubah titiknya langsung. Pengguna lain dapat mengajukan perubahan; untuk titik yang memiliki pembuat, permohonan dapat disetujui admin dan/atau pembuat titik. Untuk titik lama tanpa identitas pembuat, persetujuan admin wajib.</p>
${rows.length?`<label class="field">Pilih pemancar<select id="pointTargetSelect">${rows.map(r=>{const k=[r.provinsi,r.wilayah,r.mux].join('|'),valid=hasValidTransmitterCoordinates(r);return `<option value="${attr(k)}" ${k===state.pointSelected?'selected':''}>${esc(rowTitle(r))} — ${valid?'sudah memiliki titik':'belum memiliki titik'}</option>`}).join('')}</select></label>
<div class="result"><b>${esc(chosen?.mux||'')}</b><div>${esc(chosen?.wilayah||'')}, ${esc(chosen?.provinsi||'')}</div>
${hasCoords?`<p>Koordinat tersimpan: ${Number(chosen.latitude).toFixed(6)}, ${Number(chosen.longitude).toFixed(6)}</p><p>Pembuat titik: ${esc(chosen.point_added_by_name||pointOwner||'Belum diketahui (data lama)')}</p><p>Status hak: ${canManagePoint?'Anda dapat mengelola titik ini.':pointOwner?'Perubahan memerlukan persetujuan admin dan/atau pembuat titik.':'Pembuat belum diketahui; perubahan hanya dapat disetujui admin.'}</p>`:'<p>Titik belum tersedia. Pengguna yang login dapat menambahkan titik baru; identitas pembuat akan dicatat otomatis.</p>'}</div>
<div class="map-toolbar"><button type="button" class="small-action" id="pointGps">◎ Gunakan GPS saya</button><span class="muted">Geser peta, gunakan zoom, dan posisikan tanda bidik pada lokasi pemancar.</span></div>
<div id="pointMap" style="height:560px;border-radius:14px;z-index:1"><div class="map-crosshair">⊕</div></div><p id="pointCoordinates" class="muted">Koordinat tanda bidik: —</p>
${!hasCoords||canManagePoint||ownApproved?`<form id="pointCoordinateForm"><input type="hidden" name="latitude" id="pointLatitude"><input type="hidden" name="longitude" id="pointLongitude"><button class="action">${hasCoords?'💾 Simpan perubahan titik':'📍 Tambahkan titik pemancar'}</button></form>`:''}
${hasCoords&&!canManagePoint?`${ownApproved?`<div class="result"><b>Permohonan disetujui.</b><p>Anda dapat mengatur posisi pada peta dan menyimpan satu kali perubahan yang telah disetujui.</p></div>`:ownPending?`<div class="result"><b>Permohonan Anda sedang menunggu persetujuan.</b><p>${esc(ownPending.reason||'')}</p><small>${esc(ownPending.requested_at||'')}</small></div>`:`<form id="pointRequestForm" class="field"><h3>Ajukan perubahan titik</h3><label class="field">Alasan perubahan<textarea name="reason" required minlength="10" maxlength="1000" placeholder="Jelaskan mengapa koordinat perlu diperbarui dan sertakan dasar informasinya."></textarea></label><button class="action">Kirim permohonan persetujuan</button></form>`}`:''}
${hasCoords&&canManagePoint?`<button type="button" class="danger" data-delete-point title="Menghapus titik saja, bukan data MUX">🗑️ Hapus titik pemancar</button>`:''}
${reviewable.length?`<section class="result"><h3>Permohonan yang menunggu persetujuan</h3>${reviewable.map(q=>`<article class="result"><b>${esc(q.requester_name||q.requester)}</b><p>${esc(q.reason||'')}</p><small>${esc(q.requested_at||'')}</small><div class="map-toolbar"><button type="button" class="small-action" data-point-approve="${attr(q.requester)}">Setujui</button><button type="button" class="small-action danger" data-point-reject="${attr(q.requester)}">Tolak</button></div></article>`).join('')}</section>`:''}
`:'<p>Belum ada data pemancar. Tambahkan data siaran terlebih dahulu.</p>'}</section>`;
if(chosen&&rows.length)setTimeout(initPointMap,50);
}}
else if(state.page==='add')app.innerHTML=`<section class="panel form"><h2>✍️ Tambah data siaran</h2>${auth()?`<form id="addForm"><label class="field">Provinsi<select name="provinsi" required><option value="">Pilih provinsi</option>${options(state.provinces)}</select></label>${field('Wilayah layanan','wilayah','Jawa Barat-1')}${field('Penyelenggara MUX','mux','UHF 27 - Nama MUX')}<label class="field">Daftar kanal (pisahkan dengan koma)<textarea name="siaran" required placeholder="TVRI, Metro TV, ..."></textarea></label><button class="action">Simpan data baru</button></form>`:'<p>Login diperlukan untuk menambah data siaran.</p><button data-page="login" class="action">Login</button>'}</section>`;
else if(state.page==='edit')app.innerHTML=editPage();
else if(state.page==='report')app.innerHTML=`<section class="panel form"><h2>🚩 Laporkan kesalahan data</h2>${auth()?`<form id="reportForm">${broadcastSelect()}<label class="field">Jenis kesalahan<select name="category">${options(['Nama kanal salah','Kanal sudah tidak bersiaran','MUX/frekuensi salah','Wilayah layanan salah','Data tidak lengkap','Lainnya'])}</select></label><label class="field">Keterangan<textarea name="description" maxlength="1500" required></textarea></label>${field('Tautan bukti (opsional)','evidence_url','https://...')}<button class="action">Kirim laporan</button></form>`:'<p>Login diperlukan untuk mengirim laporan koreksi.</p><button data-page="login" class="action">Login</button>'}</section>`;
else if(state.page==='community')app.innerHTML=`<section class="panel"><h2>👥 Komunitas KTVDI</h2>${auth()?`<div id="profileCard">${profileCard(state.profile)}</div>`:'<p>Login untuk melihat profil dan komunitas.</p>'}<h3>Anggota komunitas</h3>${userList()}</section>`;
else if(state.page==='leaderboard')app.innerHTML=`<section class="panel"><h2>🏆 Leaderboard kontributor</h2>${leaderboard()}</section>`;
else if(state.page==='profile')app.innerHTML=profilePage();
else if(state.page==='admin')app.innerHTML=adminPage();
else if(state.page==='chat')app.innerHTML=`<section class="panel"><h2>🤖 Chatbot KTVDI</h2>${auth()?`<div id="chatHistory">${state.chat.map(m=>`<article class="result"><b>${m.role==='user'?'Anda':'KTVDI'}</b><p>${esc(m.text)}</p></article>`).join('')}</div><form id="chatForm" class="field"><textarea name="message" required placeholder="Tanyakan seputar TV digital..."></textarea><button class="action">Kirim</button></form>`:'<p>Login diperlukan untuk menggunakan chatbot.</p><button class="action" data-page="login">Login</button>'}</section>`;
height();if(state.page==='map')initMap();}
function databasePage(){
const rows=[...state.rows].filter(r=>{
 const q=(state.databaseQuery||'').trim().toLocaleLowerCase('id');
 const hay=[r.provinsi,r.wilayah,r.mux,...(r.siaran||[])].join(' ').toLocaleLowerCase('id');
 return (!q||hay.includes(q))&&(!state.databaseProvince||r.provinsi===state.databaseProvince);
}).sort((a,b)=>`${a.provinsi}/${a.wilayah}/${a.mux}`.localeCompare(`${b.provinsi}/${b.wilayah}/${b.mux}`,'id'));
const provinces=[...new Set(state.rows.map(r=>r.provinsi).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id'));
return `<section class="panel"><h2>🗂️ Database Siaran Digital</h2>
<p class="muted">Database ini dapat dilihat oleh semua pengunjung. Kontribusi perubahan memerlukan login dan mengikuti hak kepemilikan data.</p>
<div class="map-filterbar"><label>Cari kanal, MUX, wilayah atau provinsi<input id="databaseQuery" type="search" value="${attr(state.databaseQuery)}" placeholder="Contoh: TVRI, UHF 27, Jawa Barat"></label>
<label>Filter provinsi<select id="databaseProvince"><option value="">Semua provinsi</option>${options(provinces,state.databaseProvince)}</select></label>
<button type="button" class="small-action" id="resetDatabaseFilters">Reset filter</button></div>
<p class="muted" id="databaseCount">Menampilkan ${rows.length} dari ${state.rows.length} data MUX.</p>
${rows.length?`<div class="table-wrap"><table class="database-table"><thead><tr><th>Provinsi</th><th>Wilayah layanan</th><th>MUX / Frekuensi</th><th>Kanal</th><th>Detail</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.provinsi||'—')}</td><td>${esc(r.wilayah||'—')}</td><td>${esc(r.mux||'—')}</td><td>${esc((r.siaran||[]).join(', ')||'Belum ada kanal')}</td><td><button type="button" class="small-action" data-db-select="${attr([r.provinsi,r.wilayah,r.mux].join('|'))}">Lihat detail</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Tidak ada data yang cocok dengan pencarian.</p>'}
<p class="muted">Data ditampilkan sebagai informasi publik. Tombol pengelolaan hanya tersedia untuk pemilik data atau admin setelah memilih detail.</p>
</section>`;
}
function changeList(n){const limit=n===5?5:(state.changeLimit||10);return state.changes.length?`${state.changes.slice(0,limit).map(x=>`<article class="result"><b>${esc(x.mux||'MUX')}</b> — ${esc(({add_broadcast:'ditambahkan',edit_broadcast:'diperbarui',delete_broadcast:'dihapus',restore_broadcast:'dipulihkan'})[x.action]||'diubah')} oleh <b>${esc(x.nama||x.username||'pengguna')}</b><div class="muted">${esc(x.wilayah||'')}, ${esc(x.provinsi||'')} · ${esc(x.timestamp||'')}</div></article>`).join('')}${n!==5&&state.changes.length>limit?`<button class="small-action" data-more="changes">Tampilkan perubahan berikutnya</button><p class="muted">Menampilkan ${limit} dari ${state.changes.length} perubahan.</p>`:''}`:'<p class="muted">Belum ada perubahan data.</p>'}
function provinceStats(){const m={};state.rows.forEach(r=>{m[r.provinsi]??={mux:0,kanal:0};m[r.provinsi].mux++;m[r.provinsi].kanal+=(r.siaran||[]).length});return `<div class="table-wrap"><table><thead><tr><th>Provinsi</th><th>MUX</th><th>Kanal</th></tr></thead><tbody>${Object.entries(m).sort((a,b)=>b[1].mux-a[1].mux).map(([p,v])=>`<tr><td>${esc(p)}</td><td>${v.mux}</td><td>${v.kanal}</td></tr>`).join('')}</tbody></table></div>`}

function focusTransmitterMap(){setTimeout(()=>{const target=document.querySelector('.map-container')||document.getElementById('map');if(target)target.scrollIntoView({behavior:'auto',block:'center'})},100)}
function mapLocatedRows(){return state.rows.filter(r=>hasValidTransmitterCoordinates(r))}
function mapFilteredRows(){return mapLocatedRows().filter(r=>(!state.mapProvince||r.provinsi===state.mapProvince)&&(!state.mapArea||r.wilayah===state.mapArea))}
function drawMapLayers(){if(!state.map)return;const m=state.map;if(state.mapTransmitters)m.removeLayer(state.mapTransmitters);if(state.mapMeasurements)m.removeLayer(state.mapMeasurements);state.mapTransmitters=L.layerGroup();state.mapMeasurements=L.layerGroup();state.mapMarkerIndex={};const rows=mapFilteredRows();rows.forEach(r=>{const key=[r.provinsi,r.wilayah,r.mux].join('|'),selected=state.selected&&key===[state.selected.provinsi,state.selected.wilayah,state.selected.mux].join('|');const channels=(r.siaran||[]).length?(r.siaran||[]).map(x=>`<li>${esc(x)}</li>`).join(''):'<li>Belum ada data kanal</li>';const popup=`<div class="transmitter-popup"><div class="popup-kicker">INFORMASI PEMANCAR</div><b>Wilayah Layanan</b><div>${esc(r.wilayah||'—')}, ${esc(r.provinsi||'—')}</div><b>Nama MUX</b><div>${esc(r.mux||'—')}</div><b>Daftar Kanal</b><ul>${channels}</ul>${selected&&state.terrain?`<div class="popup-terrain">Prediksi terrain tersedia · ${esc(state.terrain.min_dbm??'—')} hingga ${esc(state.terrain.max_dbm??'—')} dBm</div>`:''}</div>`;const marker=L.marker([Number(r.latitude),Number(r.longitude)],{title:rowTitle(r)});marker.bindPopup(popup,{maxWidth:1200});if(selected)marker.setZIndexOffset(1000);marker.addTo(state.mapTransmitters);state.mapMarkerIndex[key]=marker});state.mapTransmitters.addTo(m);(state.measurements||[]).filter(x=>!state.selected||(x.provinsi===state.selected.provinsi&&x.wilayah===state.selected.wilayah&&x.mux===state.selected.mux)).forEach(x=>{const lat=Number(x.latitude),lon=Number(x.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;const q=Number(x.quality),color=q>=70?'#16a34a':q>=40?'#eab308':'#dc2626';L.circleMarker([lat,lon],{radius:7,color,fillColor:color,fillOpacity:.75,weight:2}).bindPopup(`<b>Pengukuran komunitas</b><br>${esc(x.display_name||x.username)}<br>Strength ${esc(x.strength)}% · Quality ${esc(x.quality)}%<br>SNR ${esc(x.snr??'—')} dB · BER ${esc(x.ber??'—')}<br>${esc(x.timestamp)}`).addTo(state.mapMeasurements)});state.mapMeasurements.addTo(m);const count=document.getElementById('mapCount');if(count)count.textContent=`${rows.length} titik pemancar ditampilkan · ${state.selected?'1 pemancar dipilih':'pilih marker atau MUX'}`;}
function initMap(){const el=document.getElementById('map');if(!el||!window.L)return;state.map=L.map(el,{preferCanvas:true}).setView([-2.5,118],5);const street=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(state.map);const satellite=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Tiles © Esri'});const baseLayers={'Peta jalan':street,'Satelit':satellite};const overlays={};if(state.terrain?.image_data_uri&&Array.isArray(state.terrain.bounds)){const terrain=L.imageOverlay(state.terrain.image_data_uri,state.terrain.bounds,{opacity:.82,interactive:false});overlays['Prediksi terrain DEM']=terrain;terrain.addTo(state.map);state.map.fitBounds(state.terrain.bounds,{padding:[18,18]})}L.control.layers(baseLayers,overlays,{position:'topright',collapsed:false}).addTo(state.map);L.control.scale({metric:true,imperial:false,position:'bottomleft'}).addTo(state.map);drawMapLayers();if(!state.terrain&&state.selected){const r=state.rows.find(x=>x.provinsi===state.selected.provinsi&&x.wilayah===state.selected.wilayah&&x.mux===state.selected.mux);if(hasValidTransmitterCoordinates(r))state.map.setView([Number(r.latitude),Number(r.longitude)],11)}state.map.on('mousemove',ev=>{const c=document.getElementById('mapCoordinates');if(c)c.textContent=`Koordinat: ${ev.latlng.lat.toFixed(6)}, ${ev.latlng.lng.toFixed(6)}`});const prov=document.getElementById('mapProvinceFilter'),area=document.getElementById('mapAreaFilter'),mux=document.getElementById('mapMuxFilter');if(prov)prov.addEventListener('change',()=>{state.mapProvince=prov.value;state.mapArea='';state.mapMuxSelection='';state.selected=null;state.terrain=null;state.terrainRequestedKey=null;render()});if(area)area.addEventListener('change',()=>{state.mapArea=area.value;state.mapMuxSelection='';state.selected=null;state.terrain=null;state.terrainRequestedKey=null;render()});if(mux)mux.addEventListener('change',()=>{state.mapMuxSelection=mux.value;if(!mux.value)return;window.ktvdiSelect(mux.value);const marker=state.mapMarkerIndex[mux.value];if(marker){marker.openPopup();const ll=marker.getLatLng();state.map.setView(ll,Math.max(11,state.map.getZoom()))}});const locate=document.getElementById('mapLocate');if(locate)locate.addEventListener('click',()=>{if(!navigator.geolocation){notice('Browser ini tidak mendukung GPS.');return}locate.disabled=true;locate.textContent='…';navigator.geolocation.getCurrentPosition(pos=>{const lat=pos.coords.latitude,lon=pos.coords.longitude,acc=pos.coords.accuracy;state.map.setView([lat,lon],Math.max(13,state.map.getZoom()));if(state.mapUserMarker)state.map.removeLayer(state.mapUserMarker);state.mapUserMarker=L.layerGroup().addTo(state.map);L.circle([lat,lon],{radius:acc,color:'#2563eb',fillOpacity:.08,weight:1}).addTo(state.mapUserMarker);L.marker([lat,lon]).addTo(state.mapUserMarker).bindPopup(`Lokasi saya<br>Akurasi ±${Math.round(acc)} m`).openPopup();const c=document.getElementById('mapCoordinates');if(c)c.textContent=`Lokasi GPS: ${lat.toFixed(6)}, ${lon.toFixed(6)} · akurasi ±${Math.round(acc)} m`;locate.disabled=false;locate.textContent='⌖'},err=>{notice(`GPS gagal: ${err.message}. Periksa izin lokasi browser dan koneksi HTTPS.`);locate.disabled=false;locate.textContent='⌖'},{enableHighAccuracy:true,timeout:15000,maximumAge:30000})});const reset=document.getElementById('resetMapFilters');if(reset)reset.addEventListener('click',()=>{state.mapProvince='';state.mapArea='';state.mapMuxSelection='';state.selected=null;state.terrain=null;state.terrainRequestedKey=null;render()});if(state.selected){const key=[state.selected.provinsi,state.selected.wilayah,state.selected.mux].join('|'),marker=state.mapMarkerIndex[key];if(marker)marker.openPopup()}setTimeout(()=>state.map.invalidateSize(),180)}
function initPointMap(){const el=document.getElementById('pointMap');if(!el||!window.L||!state.pointSelected)return;if(state.pointMap){state.pointMap.remove();state.pointMap=null}const row=state.rows.find(r=>[r.provinsi,r.wilayah,r.mux].join('|')===state.pointSelected);if(!row)return;const valid=hasValidTransmitterCoordinates(row);const center=valid?[Number(row.latitude),Number(row.longitude)]:[-2.5,118];const map=L.map(el,{preferCanvas:true}).setView(center,valid?14:5);state.pointMap=map;const street=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);const satellite=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Tiles © Esri'});L.control.layers({'Peta jalan':street,'Satelit':satellite},null,{position:'topright'}).addTo(map);if(valid)L.marker(center).addTo(map).bindPopup(`Koordinat tersimpan<br>${center[0].toFixed(6)}, ${center[1].toFixed(6)}`);const update=()=>{const c=map.getCenter(),lat=c.lat.toFixed(6),lon=c.lng.toFixed(6);document.getElementById('pointLatitude').value=lat;document.getElementById('pointLongitude').value=lon;document.getElementById('pointCoordinates').textContent=`Koordinat tanda bidik: ${lat}, ${lon}`};map.on('move',update);map.on('moveend',update);update();const gps=document.getElementById('pointGps');if(gps)gps.addEventListener('click',()=>{if(!navigator.geolocation){notice('Browser tidak mendukung GPS.');return}gps.disabled=true;gps.textContent='Mencari GPS…';navigator.geolocation.getCurrentPosition(pos=>{map.setView([pos.coords.latitude,pos.coords.longitude],16);gps.disabled=false;gps.textContent='◎ Gunakan GPS saya'},err=>{notice(`GPS gagal: ${err.message}`);gps.disabled=false;gps.textContent='◎ Gunakan GPS saya'},{enableHighAccuracy:true,timeout:15000,maximumAge:30000})});setTimeout(()=>map.invalidateSize(),120)}
window.ktvdiSelect=key=>{const [provinsi,wilayah,mux]=key.split('|');state.selected={provinsi,wilayah,mux};state.mapMuxSelection=key;state.terrain=null;state.terrainRequestedKey=null;state.detail=null;state.comments=[];if(state.map){drawMapLayers();const r=state.rows.find(x=>x.provinsi===provinsi&&x.wilayah===wilayah&&x.mux===mux);if(hasValidTransmitterCoordinates(r))state.map.setView([Number(r.latitude),Number(r.longitude)],11);const marker=state.mapMarkerIndex[key];if(marker)marker.openPopup();const filter=document.getElementById('mapMuxFilter');if(filter)filter.value=key}send('load_details',state.selected);focusTransmitterMap();};
function broadcastSelect(){return `<label class="field">Pilih data siaran<select name="target" required><option value="">Pilih MUX</option>${state.rows.map(r=>`<option value="${attr([r.provinsi,r.wilayah,r.mux].join('|'))}">${esc(rowTitle(r))}</option>`).join('')}</select></label>`}
function editPage(){const r=state.selected;if(!r)return '<section class="panel">Pilih data dari pencarian terlebih dahulu.</section>';const row=state.rows.find(x=>x.provinsi===r.provinsi&&x.wilayah===r.wilayah&&x.mux===r.mux)||{};const d=row.detail||{};const owner=d.created_by_username||d.last_updated_by_username||'';const canManage=!!state.auth&&(!!state.auth.admin||!!owner&&owner===state.auth.username);if(!canManage)return '<section class="panel"><h2>Akses ditolak</h2><p>Hanya pemilik data atau admin yang dapat mengedit data siaran ini.</p><button class="small-action" data-page="map">Kembali ke peta</button></section>';return `<section class="panel form"><h2>✏️ Edit data siaran</h2><p>${esc(rowTitle(r))}</p><form id="editForm">${field('Wilayah layanan','new_wilayah','Jawa Barat-1','text',r.wilayah)}${field('Penyelenggara MUX','new_mux','UHF 27 - Nama MUX','text',r.mux)}<label class="field">Daftar kanal<textarea name="siaran" required>${esc((row?.siaran||[]).join(', '))}</textarea></label><button class="action">Simpan perubahan</button></form><button id="deleteBroadcast" class="danger">Hapus data siaran</button></section>`}
function profileCard(p){return p?`<article class="result"><b>${esc(p.nama)}</b> · ⭐ ${esc(p.points)} poin<div>${esc(p.provinsi||'Lokasi belum diisi')} · ${esc(p.wilayah||'')}</div></article>`:'<p>Profil belum dimuat.</p>'}
function userList(){const limit=state.userLimit||10;return state.users.length?`${state.users.slice(0,limit).map(u=>`<article class="result"><b>${esc(u.nama)}</b> · ${esc(u.username)}<div class="muted">⭐ ${esc(u.points)} poin · ${esc(u.provinsi||'')}</div><button class="small-action" data-user="${attr(u.username)}">Lihat profil</button></article>`).join('')}${state.users.length>limit?`<button class="small-action" data-more="users">Tampilkan anggota berikutnya</button><p class="muted">Menampilkan ${limit} dari ${state.users.length} anggota.</p>`:''}`:'<p class="muted">Belum ada data anggota.</p>'}
function leaderboard(){const ranked=[...state.users].sort((a,b)=>Number(b.points)-Number(a.points)).filter(u=>Number(u.points)>0),limit=state.leaderLimit||20;return ranked.length?`<ol class="ranking">${ranked.slice(0,limit).map(u=>`<li><b>${esc(u.nama)}</b><span>⭐ ${esc(u.points)} poin</span></li>`).join('')}</ol>${ranked.length>limit?`<button class="small-action" data-more="leader">Tampilkan peringkat berikutnya</button><p class="muted">Menampilkan ${limit} dari ${ranked.length} kontributor.</p>`:''}`:'<p>Belum ada kontributor dengan poin.</p>'}
function profilePage(){const p=state.profile||{};return `<section class="panel form"><h2>👤 Profil saya</h2>${profileCard(p)}<form id="profileForm"><label class="field">Provinsi<select name="provinsi"><option value="">Pilih provinsi</option>${options(state.provinces,p.provinsi||'')}</select></label>${field('Wilayah layanan','wilayah','Jawa Barat-1','text',p.wilayah)}${field('Merk TV','tv_brand','Merk TV','text',p.tv_brand)}${field('Merk STB','stb_brand','Merk STB','text',p.stb_brand)}${field('Merk antena','antenna_brand','Merk antena','text',p.antenna_brand)}<button class="action">Simpan profil</button></form></section>`}
function adminPage(){const reports=state.reports||[],logs=state.logs||[],rl=state.reportLimit||10,ll=state.logLimit||10;return `<section class="panel"><h2>🛠️ Dashboard admin</h2><h3>Laporan koreksi (${reports.length})</h3>${reports.length?`${reports.slice(0,rl).map(r=>`<article class="result"><b>${esc(rowTitle(r))}</b><p>${esc(r.category)} · ${esc(r.description)}</p><p class="muted">${esc(r.reporter_name)} · ${esc(r.created_at)}</p>${r.evidence_url?`<a href="${attr(r.evidence_url)}" target="_blank" rel="noopener">Buka bukti</a>`:''}<form class="adminReport" data-id="${attr(r.id)}"><select name="status">${options(['Menunggu','Sedang ditinjau','Selesai','Ditolak'],r.status||'Menunggu')}</select><input name="admin_note" placeholder="Catatan admin" value="${attr(r.admin_note||'')}"><button class="small-action">Simpan</button></form></article>`).join('')}${reports.length>rl?`<button class="small-action" data-more="reports">Tampilkan laporan berikutnya</button><p class="muted">Menampilkan ${rl} dari ${reports.length} laporan.</p>`:''}`:'<p>Tidak ada laporan.</p>'}<details class="long-section"><summary>Audit log (${logs.length})</summary>${logs.slice(0,ll).map(l=>`<article class="result"><b>${esc(l.action)}</b> · ${esc(l.nama||l.username)}<div class="muted">${esc(l.timestamp)} · ${esc(l.provinsi)} / ${esc(l.wilayah)} / ${esc(l.mux)}</div>${l.before!==undefined&&l.before!==null&&['edit_broadcast','delete_broadcast','restore_broadcast'].includes(l.action)?`<button class="small-action" data-restore="${attr(l.id)}">Pulihkan versi sebelumnya</button>`:''}</article>`).join('')}${logs.length>ll?`<button class="small-action" data-more="logs">Tampilkan audit berikutnya</button><p class="muted">Menampilkan ${ll} dari ${logs.length} catatan.</p>`:''}</details></section>`}
function detailsPanel(){const r=state.selected;if(!r)return;let box=document.getElementById('detailsPanel');if(!box){box=document.createElement('section');box.id='detailsPanel';box.className='panel';app.append(box)}const row=state.rows.find(x=>x.provinsi===r.provinsi&&x.wilayah===r.wilayah&&x.mux===r.mux)||{};const d=state.detail||row.detail||{};const owner=d.created_by_username||d.last_updated_by_username||'';const canManage=!!state.auth&&(!!state.auth.admin||!!owner&&owner===state.auth.username);const measurements=state.measurements||[];const filtered=measurements.filter(m=>m.provinsi===r.provinsi&&m.wilayah===r.wilayah&&m.mux===r.mux);box.innerHTML=`<h2>📡 Data teknis & kontribusi komunitas</h2><p><b>${esc(rowTitle(r))}</b></p>${canManage?`<div class="quick-grid"><button type="button" class="action" data-edit="${attr([r.provinsi,r.wilayah,r.mux].join('|'))}">✏️ Edit data siaran</button><button type="button" class="danger" id="deleteBroadcast">🗑️ Hapus data siaran</button></div>`:''}${hasValidTransmitterCoordinates(row)&&auth()&&(state.auth?.admin||!!(d.point_added_by_username||row.point_added_by_username)&&((d.point_added_by_username||row.point_added_by_username)===state.auth?.username))?`<button type="button" class="small-action" data-manage-point="${attr([r.provinsi,r.wilayah,r.mux].join('|'))}">📍 Kelola titik pemancar</button>`:''}${hasValidTransmitterCoordinates(row)&&auth()&&!state.auth?.admin&&(d.point_added_by_username||row.point_added_by_username)!==state.auth?.username?`<p class="muted">Titik pemancar dikelola oleh kontributor yang menambahkannya atau admin. Kepemilikan data MUX tidak memberikan hak edit titik.</p>`:''}${auth()&&state.auth?.admin?`<h3>📡 Lengkapi data teknis pemancar</h3><form id="technicalForm">${field('Tinggi antena TX (m)','tx_height_m','mis. 30','text',d.tx_height_m??'')}${field('Power output (W)','tx_power_w','mis. 1000','text',d.tx_power_w??'')}${field('ERP (W)','erp_w','jika diketahui','text',d.erp_w??'')}${field('Gain antena (dBd)','antenna_gain_dbd','jika diketahui','text',d.antenna_gain_dbd??'')}${field('Rugi feeder (dB)','feeder_loss_db','jika diketahui','text',d.feeder_loss_db??'')}${field('Sumber data','technical_data_reference','referensi / tautan','text',d.technical_data_reference??'')}<button class="action secondary">Simpan data teknis</button></form>`:auth()?'<p class="muted">Data teknis pemancar hanya dapat diperbarui oleh admin.</p>':''}${auth()?`<h3>📝 Kirim pengukuran aktual TV/STB</h3><form id="measurementForm">${field('Latitude lokasi pengukuran','latitude','-6.2','text',d.latitude??'')}${field('Longitude lokasi pengukuran','longitude','106.8','text',d.longitude??'')}${field('Signal Strength (%)','strength','0–100','number','')}${field('Signal Quality (%)','quality','0–100','number','')}${field('SNR (dB), opsional','snr','mis. 24.5')}${field('BER, opsional','ber','mis. 0.000001')}<label class="field">Jenis antena<select name="antenna_type">${options(['Indoor','Outdoor','Outdoor + booster','Tidak tahu'])}</select></label><label class="field">Perangkat penerima<select name="device_type">${options(['TV DVB-T2','STB DVB-T2','Lainnya'])}</select></label>${field('Catatan','notes','Opsional')}<button class="action">Kirim hasil pengukuran</button></form>`:''}<h3>📊 Riwayat pengukuran komunitas</h3>${filtered.slice(0,state.measurementLimit||5).map(m=>`<article class="result"><b>${esc(m.display_name||m.username)}</b> · ${esc(m.timestamp)}<div>Strength ${esc(m.strength)}% · Quality ${esc(m.quality)}% · SNR ${esc(m.snr??'—')} dB · BER ${esc(m.ber??'—')}</div><div class="muted">${esc(m.device_type)} · ${esc(m.antenna_type)} · ${esc(m.latitude)}, ${esc(m.longitude)}</div></article>`).join('')||'<p>Belum ada pengukuran untuk MUX ini.</p>'}${filtered.length>(state.measurementLimit||5)?'<button class="small-action" data-more="measurements">Tampilkan pengukuran berikutnya</button>':''}<details class="long-section" open><summary>💬 Komentar pengguna (${state.comments.length})</summary>${state.comments.slice(0,state.commentLimit||5).map(c=>`<article class="result"><b>${esc(c.nama_pengguna||c.username)}</b><div class="muted">${esc(c.timestamp)}</div><p>${esc(c.text)}</p></article>`).join('')||'<p>Belum ada komentar.</p>'}${state.comments.length>(state.commentLimit||5)?'<button class="small-action" data-more="comments">Tampilkan komentar berikutnya</button>':''}</details>${auth()?`<form id="commentForm"><label class="field">Tulis komentar<textarea name="text" maxlength="1500" required></textarea></label><button class="action">Kirim komentar (+1 poin)</button></form>`:'<p>Login untuk menulis komentar.</p>'}`;box.scrollIntoView({behavior:'smooth',block:'start'})}
// Global delegated navigation and forms.
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-toggle-password]');if(toggle){const input=document.querySelector('#loginForm input[name="password"]');if(input){input.type=input.type==='password'?'text':'password';toggle.textContent=input.type==='password'?'👁 Lihat password':'🙈 Tutup password'}return}const more=e.target.closest('[data-more]');if(more){const k=more.dataset.more;if(k==='changes')state.changeLimit=(state.changeLimit||10)+10;else if(k==='users')state.userLimit=(state.userLimit||10)+10;else if(k==='leader')state.leaderLimit=(state.leaderLimit||20)+20;else if(k==='reports')state.reportLimit=(state.reportLimit||10)+10;else if(k==='logs')state.logLimit=(state.logLimit||10)+10;else if(k==='measurements')state.measurementLimit=(state.measurementLimit||5)+5;else if(k==='comments')state.commentLimit=(state.commentLimit||5)+5;render();if(state.page==='map'&&state.selected)detailsPanel();return}if(e.target.closest('#resetDatabaseFilters')){state.databaseQuery='';state.databaseProvince='';render();return}const dbSelect=e.target.closest('[data-db-select]');if(dbSelect){const [provinsi,wilayah,mux]=dbSelect.dataset.dbSelect.split('|');state.selected={provinsi,wilayah,mux};state.detail=null;state.comments=[];state.measurements=[];send('load_details',state.selected);return}const navEl=e.target.closest('[data-page]');if(navEl){e.preventDefault();const page=navEl.dataset.page;if(page==='login'&&auth()){send('logout');return}state.page=page;if(['community','leaderboard','profile'].includes(page)&&auth())send('load_community');if(page==='admin'&&state.auth?.admin)send('load_admin');if(page==='map')send('load_measurements');if(page==='addPoint'&&auth()){state.pointSelected=state.pointSelected||null;send('load_point_requests')}render();return}const approvePoint=e.target.closest('[data-point-approve]');if(approvePoint){const [sp,sw,sm]=(state.pointSelected||'').split('|');const provinsi=approvePoint.dataset.provinsi||sp,wilayah=approvePoint.dataset.wilayah||sw,mux=approvePoint.dataset.mux||sm;send('approve_point_change_request',{provinsi,wilayah,mux,requester:approvePoint.dataset.pointApprove});return}const rejectPoint=e.target.closest('[data-point-reject]');if(rejectPoint){const [sp,sw,sm]=(state.pointSelected||'').split('|');const provinsi=rejectPoint.dataset.provinsi||sp,wilayah=rejectPoint.dataset.wilayah||sw,mux=rejectPoint.dataset.mux||sm;if(confirm('Tolak permohonan perubahan titik ini?'))send('reject_point_change_request',{provinsi,wilayah,mux,requester:rejectPoint.dataset.pointReject});return}if(e.target.closest('[data-delete-point]')){if(state.pointSelected&&confirm('Hapus titik pemancar ini? Data MUX, kanal siaran, dan informasi teknis tidak akan dihapus.')){const [provinsi,wilayah,mux]=state.pointSelected.split('|');send('delete_coordinates',{provinsi,wilayah,mux})}return}const managePoint=e.target.closest('[data-manage-point]');if(managePoint){state.pointSelected=managePoint.dataset.managePoint;state.page='addPoint';render();return}const sel=e.target.closest('[data-select]');if(sel){const [provinsi,wilayah,mux]=sel.dataset.select.split('|');state.selected={provinsi,wilayah,mux};state.terrain=null;state.terrainRequestedKey=null;state.detail=null;state.comments=[];send('load_details',state.selected);return}const ed=e.target.closest('[data-edit]');if(ed){const [provinsi,wilayah,mux]=ed.dataset.edit.split('|');state.selected={provinsi,wilayah,mux};state.page='edit';render();return}const restore=e.target.closest('[data-restore]');if(restore&&confirm('Pulihkan snapshot data ini?'))send('admin_restore',{log_id:restore.dataset.restore});const user=e.target.closest('[data-user]');if(user)send('load_user_profile',{username:user.dataset.user});const terrain=e.target.closest('[data-terrain]');if(terrain&&state.selected){state.terrainRequestedKey=[state.selected.provinsi,state.selected.wilayah,state.selected.mux].join('|');notice('Menghitung prediksi terrain dari data DEM…');send('calculate_terrain',state.selected);}const delCoord=e.target.closest('[data-delete-coordinates]');if(delCoord&&state.selected&&confirm('Hapus koordinat pemancar ini?'))send('delete_coordinates',state.selected);if(e.target.id==='logout')send('logout');if(e.target.id==='deleteBroadcast'&&confirm('Hapus data MUX ini?'))send('delete_broadcast',state.selected);});

document.addEventListener('input',e=>{if(e.target&&e.target.id==='databaseQuery'){state.databaseQuery=e.target.value;const active=document.activeElement;render();const input=document.getElementById('databaseQuery');if(input){input.focus();input.setSelectionRange(input.value.length,input.value.length)}return}});
document.addEventListener('change',e=>{if(e.target&&e.target.id==='databaseProvince'){state.databaseProvince=e.target.value;render();return}if(e.target&&e.target.id==='pointTargetSelect'){state.pointSelected=e.target.value;render();return}if(e.target&&e.target.id==='autoTerrainToggle'){state.terrainAuto=!!e.target.checked;if(state.terrainAuto&&state.selected&&!state.terrain){const key=[state.selected.provinsi,state.selected.wilayah,state.selected.mux].join('|');if(state.terrainRequestedKey!==key){state.terrainRequestedKey=key;notice('Menghitung prediksi terrain dari data DEM…');send('calculate_terrain',state.selected)}}}});
document.getElementById('menuToggle').addEventListener('click',()=>document.getElementById('nav').classList.toggle('open'));
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f).entries());if(f.id==='loginForm')send('login',d);else if(f.id==='terrainSimulationForm'){if(!state.selected){notice('Pilih MUX bertitik terlebih dahulu.');return}state.terrainRequestedKey=[state.selected.provinsi,state.selected.wilayah,state.selected.mux].join('|');send('calculate_terrain',{...state.selected,erp_w:d.sim_erp_w,tx_height_m:d.sim_tx_height_m,rx_height_m:d.sim_rx_height_m,rx_threshold_dbm:d.sim_rx_threshold_dbm,extra_loss_db:d.sim_extra_loss_db})}else if(f.id==='searchForm')send('search',d);else if(f.id==='registerForm')send('register_request',d);else if(f.id==='registerVerify')send('register_verify',d);else if(f.id==='forgotRequest')send('forgot_request',d);else if(f.id==='forgotReset')send('forgot_reset',d);else if(f.id==='addForm')send('add_broadcast',d);else if(f.id==='pointCoordinateForm'){const [provinsi,wilayah,mux]=(state.pointSelected||'').split('|');send('save_coordinates',{...d,provinsi,wilayah,mux})}else if(f.id==='pointRequestForm'){const [provinsi,wilayah,mux]=(state.pointSelected||'').split('|');send('submit_point_change_request',{...d,provinsi,wilayah,mux})}else if(f.id==='editForm')send('edit_broadcast',{...d,...state.selected});else if(f.id==='profileForm')send('save_profile',d);else if(f.id==='commentForm')send('add_comment',{...d,...state.selected});else if(f.id==='technicalForm')send('save_technical',{...d,...state.selected});else if(f.id==='coordinateForm')send('save_coordinates',{...d,...state.selected});else if(f.id==='measurementForm')send('submit_measurement',{...d,...state.selected});else if(f.id==='reportForm'){const [provinsi,wilayah,mux]=(d.target||'').split('|');send('submit_report',{...d,provinsi,wilayah,mux})}else if(f.id==='chatForm'){state.chat.push({role:'user',text:d.message});render();send('chat',d)}else if(f.classList.contains('adminReport'))send('admin_report_update',{id:f.dataset.id,...d});});
window.addEventListener('message',e=>{const d=e.data;if(!d||d.type!=='streamlit:render')return;const a=d.args||{};state.stats=a.stats||state.stats;state.rows=a.rows||state.rows;state.changes=a.changes||state.changes;state.provinces=a.provinces||state.provinces;state.mapLastUpdated=a.map_last_updated??state.mapLastUpdated;state.auth=a.auth||state.auth;state.result=a.result||null;if(state.result?.action==='login'&&state.result.ok){state.auth={username:state.result.username,nama:state.result.nama,points:state.result.points,admin:state.result.admin};state.page='beranda'}if(state.result?.action==='logout'&&state.result.ok){state.auth=null;state.page='beranda';state.selected=null;state.terrain=null}let showDetail=false, message='';if(state.result){const r=state.result;if(r.stats)state.stats=r.stats;if(r.results)state.searchResults=r.results;if(r.comments){state.comments=r.comments;showDetail=true}if(r.detail){state.detail=r.detail;showDetail=true}if(r.measurements){state.measurements=r.measurements;showDetail=true}if(r.terrain){state.terrain=r.terrain;showDetail=true}if(r.users){state.users=r.users;state.profile=r.profile||state.profile}if(r.user_profile){state.viewedProfile=r.user_profile}if(r.reports){state.reports=r.reports;state.logs=r.logs||[]}if(r.point_requests){state.pointRequests=r.point_requests}if(r.ok&&r.action==='save_coordinates'){state.pointRequests=(state.pointRequests||[]).filter(q=>!(q.provinsi===state.pointSelected?.split('|')[0]&&q.wilayah===state.pointSelected?.split('|')[1]&&q.mux===state.pointSelected?.split('|')[2]&&q.requester===state.auth?.username))}if(r.reply){state.chat.push({role:'assistant',text:r.reply})}if(r.message)message=r.message;if(r.ok&&['submit_point_change_request','approve_point_change_request','reject_point_change_request'].includes(r.action)){send('load_point_requests')}if(r.ok&&['add_broadcast','edit_broadcast','delete_broadcast','save_profile','add_comment','submit_report','admin_report_update','admin_restore','register_verify','forgot_reset','save_technical','save_coordinates','delete_coordinates','submit_measurement','calculate_terrain'].includes(r.action)){send('refresh')}}render();if(state.searchResults&&state.page==='search')showResults(state.searchResults);if(showDetail&&state.selected)detailsPanel();if(message)notice(message);if(state.viewedProfile&&state.page==='community'){const c=document.getElementById('profileCard');if(c)c.innerHTML=profileCard(state.viewedProfile)}if(state.page==='map'&&state.selected){focusTransmitterMap();if(state.result?.action==='load_details'&&state.terrainAuto){const selectedRow=state.rows.find(x=>x.provinsi===state.selected.provinsi&&x.wilayah===state.selected.wilayah&&x.mux===state.selected.mux);const key=[state.selected.provinsi,state.selected.wilayah,state.selected.mux].join('|');if(hasValidTransmitterCoordinates(selectedRow)&&/\bUHF\s*(2[1-9]|3[0-9]|4[0-8])\b/i.test(state.selected.mux)&&state.terrainRequestedKey!==key){state.terrainRequestedKey=key;notice('Menghitung prediksi terrain dari DEM MAPZEN…');send('calculate_terrain',state.selected)}}}});
window.parent.postMessage({isStreamlitMessage:true,type:'streamlit:componentReady',apiVersion:1},'*');window.parent.postMessage({isStreamlitMessage:true,type:'streamlit:setFrameHeight',height:700},'*');
})();
